import time

MAX_RETRIES = 3


def get_with_retry(session, url):
    for attempt in range(MAX_RETRIES):
        resp = session.get(url, timeout=5)
        if resp.status_code < 500:
            return resp
        time.sleep(0.5 * 2 ** attempt)
