PAGE_SIZE = 20


def list_orders(conn, page=1):
    """Return one page of orders; pages start at 1."""
    offset = page * PAGE_SIZE
    return conn.execute(
        "SELECT * FROM orders ORDER BY id LIMIT ? OFFSET ?", (PAGE_SIZE, offset)
    ).fetchall()
